-- GENERATED by scripts/gen-suites.mjs from registry/db-schema.json — RC Code request (item code / extension code). READ-ONLY queries for DBeaver, SIT connection only.
-- Replace {NO} with the document number (e.g. RC26…). Mapping verified: yes — SIT 2026-11-24: CU 19897/19956, CE 9862/9883 doc ids are CM_REQUEST_CODE.REQUEST_ID; numbers RNC120118-1159 (CU) / RNE… (CE)

-- Status history (CU); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.cm_workflow_status w
 where w.doc_type = 'CU'
   and w.doc_id in (select request_id from ngep_sit.cm_request_code where doc_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Status history (CE); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.cm_workflow_status w
 where w.doc_type = 'CE'
   and w.doc_id in (select request_id from ngep_sit.cm_request_code where doc_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Open BPM tasks: who the task is assigned to (task name = activityname)
select activityname, state, assignees, acquiredby, to_char(createddate, 'YYYY-MM-DD HH24:MI:SS') as created
  from SIT01_SOAINFRA.wftask@SITSOA
 where customattributestring1 = '{NO}'
 order by createddate;

-- Every status a CU has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.cm_workflow_status w
 where w.doc_type = 'CU' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;

-- Every status a CE has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.cm_workflow_status w
 where w.doc_type = 'CE' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;
